#' Stocking Solution
#'
#' 
#' @param data .
#' @param tc .
#' @param munit .
#' @param vunit .
#' @param sr .
#' @param sv .
#' @param mw .
#' @param wth .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$a} \tab \tab \tab \tab \tab an array of tables \cr
#'   \code{results$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$t$asDF}
#'
#' \code{as.data.frame(results$t)}
#'
#' @export
Stocking <- function(
    data,
    tc = 1,
    munit,
    vunit,
    sr = 20,
    sv = 2,
    mw = 58.44,
    wth = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Stocking requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- StockingOptions$new(
        tc = tc,
        munit = munit,
        vunit = vunit,
        sr = sr,
        sv = sv,
        mw = mw,
        wth = wth)

    analysis <- StockingClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

